, 53646378, 53646197, 53645757, 53646461, 53646364, 53646169, 53646640, 53645983, 53645915, 53645778, 53645772, 53646520, 53646597, 53645799, 53646234, 53646187, 53646416, 53646321, 53645845, 53645779, 53646551, 53646667, 53646743, 53646272, 53646482, 53646092, 53646708, 53645800, 53645669, 53645914, 53645775, 53646175, 53646701, 53646576, 53646265, 53646487, 53646690, 53645811, 53646699, 53645703, 53646125, 53646689, 53646535, 53645732, 53646147, 53646559, 53646739, 53646497, 53645968, 53646681, 53645936, 53646392, 53646430, 53646233, 53646192, 53646507, 53646097, 53646208, 53646150, 53646573, 53646565, 53645908, 53646412, 53646075, 53646591, 53646013, 53645784, 53646067, 53645980, 53645756, 53646059, 53646017, 53646697, 53646605, 53646088, 53646039, 53646099, 53646238, 53646031, 53646663, 53646600, 53645894, 53646071, 53646427, 53645768, 53646684);
----------------------------
SELECT
    nextval('hibernate_sequence') AS id,
    id_turma,
    data_aula::date AS data_aula,
    current_date AS criado_em,
    1 AS numero_aulas,
    3 AS tipo,
    'Sábado Letivo' AS descricao
INTO TEMP aulas_extra_para_adicionar
FROM (
    WITH datas (dia) AS (
        VALUES
        	('2025-10-18')
    ),
    aulas_comuns AS (
        SELECT
            CASE
                WHEN t.id_turma_agrupadora IS NOT NULL THEN t.id_turma_agrupadora
                ELSE t.id_turma
            END AS id_turma,
            d.dia AS data_aula
        FROM
            ensino.turma t,
            datas d
        WHERE
            t.id_situacao_turma NOT IN (4, 9)
            AND t.ano = 2025
            AND NOT EXISTS (
                SELECT 1
                FROM ava.aula_extra ae
                WHERE
                    ae.id_turma = CASE WHEN t.id_turma_agrupadora IS NOT NULL THEN t.id_turma_agrupadora ELSE t.id_turma END
                    AND ae.data_aula = d.dia::date
            )
    ),
    aulas_adjuntas AS (
        SELECT
            t.id_turma AS id_turma,
            d.dia AS data_aula
        FROM
            ensino.turma t
        JOIN basico.turma_serie ts ON
            t.id_turma_serie = ts.id_turma_serie
        JOIN basico.curriculo_basico cb ON
            cb.id_curriculo_basico = ts.id_curriculo_medio
        JOIN ensino.docente_turma dt ON
            dt.id_turma = t.id_turma
        JOIN basico.curriculo_basico_componente cbc ON
            cbc.id_curriculo_basico = ts.id_curriculo_medio
            AND cbc.permite_alocacao_adjunto
            AND cbc.id_componente_curricular = t.id_disciplina
        CROSS JOIN datas d
        WHERE
            dt.ativo
            AND NOT dt.finalizada
            AND (now() BETWEEN dt.data_inicio AND dt.data_fim)
            AND t.id_turma_agrupadora IS NOT NULL
            AND NOT EXISTS (
                SELECT 1
                FROM ava.aula_extra ae
                WHERE
                    ae.id_turma = t.id_turma
                    AND ae.data_aula = d.dia::date
            )
    )
    SELECT id_turma, data_aula FROM aulas_comuns
    UNION
    SELECT id_turma, data_aula FROM aulas_adjuntas
) AS aulas_para_processar;

INSERT INTO ava.aula_extra (id, id_turma, data_aula, criado_em, numero_aulas, tipo, descricao)
SELECT
    id,
    id_turma,
    data_aula,
    criado_em,
    numero_aulas,
    tipo,
    descricao
FROM aulas_extra_para_adicionar;



SELECT 'DELETE FROM ava.aula_extra WHERE id IN ( ' || string_agg(id::TEXT,',') || ');'
FROM aulas_extra_para_adicionar;

ROLLBACK;